def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Count opponent's defections so far
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')

    # Last few moves
    last_opp = history[-1][1] if n >= 1 else 'C'
    last_mine = history[-1][0] if n >= 1 else 'C'

    # Early: cooperate, but retaliate immediately if opponent defects
    if n <= 2:
        if opp_defects > 0:
            return 'D'
        return 'C'

    # Estimate opponent's defection rate
    rate = opp_defects / n

    # If opponent is highly cooperative, cooperate but occasionally test
    if rate <= 0.1:
        # Keep cooperating, but rare random defection to probe
        if rng.random() < 0.02:
            return 'D'
        return 'C'

    # If opponent defects moderately, play tit-for-tat with forgiveness
    if rate <= 0.5:
        if last_opp == 'D':
            # Forgive with some probability if opponent was previously cooperative
            if rng.random() < 0.3 and opp_defects < n // 3:
                return 'C'
            return 'D'
        else:
            # Occasionally defect to keep opponent in check
            if rng.random() < 0.05:
                return 'D'
            return 'C'

    # Opponent is heavily defecting: defect almost always, but rarely cooperate to avoid endless DD
    if rate <= 0.8:
        if last_opp == 'C':
            return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Very defection-heavy opponent: pure defection with occasional C to reset
    if rng.random() < 0.03:
        return 'C'
    return 'D'

